"""nfare.py -- a tiny regex engine with NO catastrophic backtracking.

Supported syntax:
    literals        a b c ...
    .               any character except newline (like Python's re default)
    |               alternation
    ()              grouping
    * + ?           quantifiers
    {n}             exact repetition, desugared at parse time into n copies
    \\x              escape for a literal metacharacter

Strategy (Thompson 1968 / Russ Cox "Regular Expression Matching Can Be
Simple and Fast"):
    1. Parse the pattern into an AST.
    2. Compile the AST into an NFA with epsilon transitions
       (Thompson construction; states are plain integers).
    3. Simulate the NFA on the input by tracking the *set* of states the
       machine could be in after each character.  Each input character is
       examined exactly once and every state pair is visited at most once,
       so matching runs in O(len(pattern) * len(string)) time -- there is
       no backtracking at all, hence no catastrophic blowup on patterns
       like (a?){25}a{25}.
"""

from __future__ import annotations

import copy
import string
from typing import AbstractSet, Dict, FrozenSet, List, Optional, Tuple

# ---------------------------------------------------------------------------
# AST
# ---------------------------------------------------------------------------


class Node:
    pass


class Char(Node):  # a single literal character
    def __init__(self, ch: str) -> None:
        self.ch = ch


class Dot(Node):  # '.' -- any char except '\n'
    pass


class Concat(Node):
    def __init__(self, parts: List[Node]) -> None:
        self.parts = parts


class Alt(Node):
    def __init__(self, options: List[Node]) -> None:
        self.options = options


class Star(Node):
    def __init__(self, child: Node) -> None:
        self.child = child


class Plus(Node):  # desugars to Concat([child, Star(child)])
    def __init__(self, child: Node) -> None:
        self.child = child


class Opt(Node):  # '?' -- desugars to Alt([child, Empty])
    def __init__(self, child: Node) -> None:
        self.child = child


class Empty(Node):  # matches the empty string
    pass


# ---------------------------------------------------------------------------
# Parser (recursive descent).  Desugars {n}, + and ? immediately.
# ---------------------------------------------------------------------------

_META = set(".*+?|(){}[]\\^$")


class _Parser:
    def __init__(self, pattern: str) -> None:
        self.pat = pattern
        self.i = 0

    def peek(self) -> Optional[str]:
        return self.pat[self.i] if self.i < len(self.pat) else None

    def take(self) -> str:
        ch = self.peek()
        if ch is None:
            raise ValueError("unexpected end of pattern")
        self.i += 1
        return ch

    def parse(self) -> Node:
        node = self.parse_alt()
        if self.i != len(self.pat):
            raise ValueError(f"unexpected '{self.pat[self.i]}' at {self.i}")
        return node

    def parse_alt(self) -> Node:
        options = [self.parse_concat()]
        while self.peek() == "|":
            self.take()
            options.append(self.parse_concat())
        return options[0] if len(options) == 1 else Alt(options)

    def parse_concat(self) -> Node:
        parts: List[Node] = []
        while self.peek() is not None and self.peek() not in "|)":
            parts.append(self.parse_repeat())
        if not parts:
            return Empty()
        return parts[0] if len(parts) == 1 else Concat(parts)

    def parse_repeat(self) -> Node:
        atom = self.parse_atom()
        while True:
            op = self.peek()
            if op == "*":
                self.take()
                atom = Star(atom)
            elif op == "+":
                self.take()
                atom = Plus(atom)
            elif op == "?":
                self.take()
                atom = Opt(atom)
            elif op == "{":
                # {n}: exact repetition.  Desugar into n copies of the atom.
                save = self.i
                self.take()
                digits = ""
                while self.peek() is not None and self.peek().isdigit():
                    digits += self.take()
                if not digits or self.peek() != "}":
                    raise ValueError("unsupported/invalid repeat {n}")
                self.take()
                n = int(digits)
                if n > 1000:
                    raise ValueError("repeat count too large")
                atom = Concat([copy.deepcopy(atom) for _ in range(n)]) if n else Empty()
            else:
                return atom

    def parse_atom(self) -> Node:
        ch = self.peek()
        if ch is None:
            raise ValueError("unexpected end of pattern")
        if ch == "(":
            self.take()
            node = self.parse_alt()
            if self.take() != ")":
                raise ValueError("missing ')'")
            return node
        if ch == ".":
            self.take()
            return Dot()
        if ch == "\\":
            self.take()
            return Char(self.take())  # escaped metacharacter -> literal
        if ch in ")*+?|":
            raise ValueError(f"unexpected '{ch}' at position {self.i}")
        self.take()
        return Char(ch)


# ---------------------------------------------------------------------------
# Thompson NFA construction
# ---------------------------------------------------------------------------

# Symbol stored on transitions: a concrete character, or DOT_SYM for '.'.
DOT_SYM = object()


class NFA:
    """NFA as adjacency lists over integer states.

    trans[s]: dict symbol -> list of successor states (consuming edges)
    eps[s]:   list of successor states reachable without consuming input
    """

    def __init__(self) -> None:
        self.trans: List[Dict[object, List[int]]] = []
        self.eps: List[List[int]] = []

    def new_state(self) -> int:
        self.trans.append({})
        self.eps.append([])
        return len(self.trans) - 1


