    """Compile `pattern`; return (nfa, start_state, accept_state)."""
    ast = _Parser(pattern).parse()
    nfa = NFA()

    def build(node: Node) -> Tuple[int, int]:
        """Return (start, accept) fragment for `node`."""
        if isinstance(node, Empty):
            s = nfa.new_state()
            return s, s
        if isinstance(node, Char):
            s, a = nfa.new_state(), nfa.new_state()
            nfa.trans[s].setdefault(node.ch, []).append(a)
            return s, a
        if isinstance(node, Dot):
            s, a = nfa.new_state(), nfa.new_state()
            nfa.trans[s].setdefault(DOT_SYM, []).append(a)
            return s, a
        if isinstance(node, Concat):
            start, prev_accept = build(node.parts[0])
            for part in node.parts[1:]:
                ps, pa = build(part)
                nfa.eps[prev_accept].append(ps)
                prev_accept = pa
            return start, prev_accept
        if isinstance(node, Alt):
            s, a = nfa.new_state(), nfa.new_state()
            for opt in node.options:
                os_, oa = build(opt)
                nfa.eps[s].append(os_)
                nfa.eps[oa].append(a)
            return s, a
        if isinstance(node, Star):
            s, a = nfa.new_state(), nfa.new_state()
            cs, ca = build(node.child)
            nfa.eps[s].append(cs)
            nfa.eps[s].append(a)      # skip: zero repetitions
            nfa.eps[ca].append(cs)    # loop back for more repetitions
            nfa.eps[ca].append(a)
            return s, a
        if isinstance(node, Plus):
            # e+ == e e*
            cs, ca = build(node.child)
            inner_s, inner_a = build(Star(node.child))
            nfa.eps[ca].append(inner_s)
            return cs, inner_a
        if isinstance(node, Opt):
            s, a = nfa.new_state(), nfa.new_state()
            cs, ca = build(node.child)
            nfa.eps[s].append(cs)
            nfa.eps[s].append(a)
            nfa.eps[ca].append(a)
            return s, a
        raise TypeError(f"unknown node {node!r}")

    start, accept = build(ast)
    return nfa, start, accept


# ---------------------------------------------------------------------------
# Simulation: set-of-states, one pass over the input.  No backtracking.
# ---------------------------------------------------------------------------


def _epsilon_closure(nfa: NFA, states: Iterable_states) -> FrozenSet[int]:
    """All states reachable from `states` via zero or more epsilon edges."""
    stack = list(states)
    seen = set(states)
    while stack:
        s = stack.pop()
        for t in nfa.eps[s]:
            if t not in seen:
                seen.add(t)
                stack.append(t)
    return frozenset(seen)


# small alias to keep the signature readable
Iterable_states = AbstractSet[int]


def fullmatch(pattern: str, s: str) -> bool:
    """Return True iff `pattern` matches ALL of `s`.

    Simulates the Thompson NFA keeping the full set of reachable states;
    each character step is O(|states|), independent of input history.
    """
    nfa, start, accept = compile_nfa(pattern)
    current = _epsilon_closure(nfa, (start,))
    for ch in s:
        nxt: set = set()
        for st in current:
            edges = nfa.trans[st]
            targets = edges.get(ch)
            if targets is None and ch != "\n":
                targets = edges.get(DOT_SYM)  # '.' matches any non-newline
            if targets:
                nxt.update(targets)
        current = _epsilon_closure(nfa, nxt) if nxt else frozenset()
        if not current:
            return False  # dead early -- still linear work overall
    return accept in current


# Convenience: precompiled pattern object.


class Pattern:
    def __init__(self, pattern: str) -> None:
        self.nfa, self.start, self.accept = compile_nfa(pattern)

    def fullmatch(self, s: str) -> bool:
        current = _epsilon_closure(self.nfa, (self.start,))
        for ch in s:
            nxt: set = set()
            for st in current:
                edges = self.nfa.trans[st]
                targets = edges.get(ch)
                if targets is None and ch != "\n":
                    targets = edges.get(DOT_SYM)
                if targets:
                    nxt.update(targets)
            current = _epsilon_closure(self.nfa, nxt) if nxt else frozenset()
            if not current:
                return False
        return self.accept in current


_ALPHABET = string.ascii_letters + string.digits + "_-"

